import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles.css';
import '../assets/home-dark.css';
import '../assets/server-theme.css';

import logoNuevo from '../assets/img/logonuevo.png';
import UserMenu from '../components/UserMenu.jsx';

const DISCORD_URL = 'https://discord.rustaco.site';
const STORE_URL = 'https://store.rustaco.co';
const SUPPORT_URL = 'https://discord.rustaco.site';
const SERVER_NAME = 'Rustaco.co - Main 2x';

// ─── EDITA AQUÍ LAS REGLAS ─────────────────────────────────────────────────
// Cada sección agrupa reglas relacionadas. La numeración es continua y se
// genera automáticamente, así que puedes reordenar o añadir reglas libremente.
const RULE_SECTIONS = [
  {
    section: 'Cuentas y acceso',
    icon: 'bi-person-badge',
    rules: [
      {
        title: 'Una cuenta por jugador',
        text: 'Solo puedes jugar con tu cuenta principal de Steam. El uso de cuentas alternativas (alts) para espiar, ocupar slots, falsear estadísticas o sortear sanciones está prohibido y conlleva el ban de todas las cuentas asociadas.',
      },
      {
        title: 'Evasión de sanciones',
        text: 'Intentar evadir un ban mediante VPN, nuevas cuentas o suplantación reinicia y prolonga la sanción de forma permanente. La única vía válida para revisar un ban es la apelación por ticket.',
      },
      {
        title: 'Historial de bans del juego',
        text: 'No se permite el acceso a cuentas con un VAC o Game Ban de Rust de antigüedad inferior a 365 días. Convivir, compartir base o aliarse con un jugador baneado del servidor también es sancionable.',
      },
      {
        title: 'Cuenta verificable',
        text: 'El staff puede solicitar que tu perfil de Steam sea público durante una investigación. Negarse a colaborar con una investigación activa puede derivar en restricción temporal.',
      },
    ],
  },
  {
    section: 'Trampas y software de terceros',
    icon: 'bi-shield-shaded',
    rules: [
      {
        title: 'Cero tolerancia a las trampas',
        text: 'Cualquier software que otorgue ventaja injusta —aimbot, ESP/wallhack, spinbot, no-recoil, radar— resulta en ban permanente e irrevocable a la primera infracción, sin excepciones.',
      },
      {
        title: 'Scripts y macros',
        text: 'Están prohibidos los scripts y macros que automaticen acciones del juego, incluyendo macros de no-recoil, auto-farm, auto-clicker y combinaciones de teclas que ejecuten múltiples acciones con una sola pulsación.',
      },
      {
        title: 'Abuso de bugs y exploits',
        text: 'Aprovechar fallos del juego o de los plugins para obtener ventaja (duplicación de objetos, atravesar paredes, stacks ilegales, exploits de terreno) está prohibido. Reportar un exploit en lugar de abusarlo puede ser recompensado.',
      },
    ],
  },
  {
    section: 'Conducta y comunicación',
    icon: 'bi-chat-dots',
    rules: [
      {
        title: 'Respeto mínimo',
        text: 'El pique y la rivalidad propios del juego son parte de Rust. Lo que no se tolera es el acoso dirigido y sostenido, el discurso de odio (racismo, xenofobia, homofobia) ni los insultos discriminatorios en chat de voz o texto.',
      },
      {
        title: 'Doxxing y amenazas',
        text: 'Compartir información personal de otro jugador sin su consentimiento, así como amenazas reales (a la integridad física, DDoS, swatting), conlleva ban permanente y puede ser reportado a las autoridades.',
      },
      {
        title: 'Spam y publicidad',
        text: 'No se permite el spam en el chat ni la publicidad de otros servidores, comunidades o servicios ajenos a Rustaco, tanto en el juego como en Discord.',
      },
    ],
  },
  {
    section: 'Economía, tienda y staff',
    icon: 'bi-shop',
    rules: [
      {
        title: 'Estafas',
        text: 'Las estafas en intercambios entre jugadores (tradeos de objetos, servicios o cuentas) están prohibidas. Realiza tus tradeos con jugadores de confianza; el staff no reembolsa pérdidas por estafas entre particulares.',
      },
      {
        title: 'Compras y contracargos',
        text: 'Iniciar un contracargo (chargeback) o disputa sobre una compra de la tienda resulta en ban permanente. Cualquier problema con un pago debe resolverse mediante un ticket de soporte.',
      },
      {
        title: 'Suplantación de staff',
        text: 'Hacerse pasar por miembro del staff, administrador o moderador para engañar a otros jugadores es una falta grave sancionada con ban permanente.',
      },
      {
        title: 'Decisiones del staff',
        text: 'Las decisiones del staff son definitivas dentro del juego. Si consideras que una sanción fue un error, no discutas en el chat: abre un ticket de apelación con tu evidencia y será revisado.',
      },
    ],
  },
];
// ───────────────────────────────────────────────────────────────────────────

export default function Rules() {
  React.useEffect(() => {
    document.body.classList.add('has-video-bg');
    return () => document.body.classList.remove('has-video-bg');
  }, []);

  let ruleNumber = 0;

  return (
    <div className="rw-page">
      <header className="rw-nav">
        <Link to="/" className="rw-nav-brand">
          <img src={logoNuevo} alt="Rustaco" />
          <span>
            Rust<em>aco</em>
          </span>
        </Link>

        <nav className="rw-nav-links" aria-label="Navegación">
          <Link to="/" className="rw-nav-link">Inicio</Link>
          <a href={STORE_URL} target="_blank" rel="noopener noreferrer" className="rw-nav-link">Store</a>
          <span className="rw-nav-link" style={{ color: '#fff' }} aria-current="page">
            Reglas
          </span>
          <Link to="/maps" className="rw-nav-link">Maps</Link>
          <Link to="/events" className="rw-nav-link">Leaderboard</Link>
          <a href={SUPPORT_URL} target="_blank" rel="noopener noreferrer" className="rw-nav-link">Soporte</a>
          <a href={DISCORD_URL} target="_blank" rel="noopener noreferrer" className="rw-nav-link">
            Discord
          </a>
        </nav>

        <div className="rw-nav-right">
          <UserMenu />
          <a className="rw-btn rw-btn--discord rw-btn--sm" href={DISCORD_URL} target="_blank" rel="noopener noreferrer">
            <i className="bi bi-discord" /> Discord
          </a>
        </div>
      </header>

      <main className="rw-lb-main">
        <div className="rw-lb-head">
          <span className="rw-section-kicker">Juega limpio</span>
          <h1>Reglas del servidor</h1>
          <p>
            Reglamento oficial de <b>{SERVER_NAME}</b>. Al conectarte aceptas cumplir
            estas normas en su totalidad. Su desconocimiento no exime de su cumplimiento.
          </p>
        </div>

        <div className="rw-rules-content">
          {RULE_SECTIONS.map((section) => (
            <section key={section.section}>
              <div className="rw-rules-sectionhead">
                <i className={`bi ${section.icon}`} aria-hidden="true" />
                <h2>{section.section}</h2>
              </div>
              <div className="rw-rules-list">
                {section.rules.map((rule) => {
                  ruleNumber += 1;
                  return (
                    <article key={rule.title} className="rw-rule-card">
                      <span className="rw-rule-num">{ruleNumber}</span>
                      <div>
                        <h3>{rule.title}</h3>
                        <p>{rule.text}</p>
                      </div>
                    </article>
                  );
                })}
              </div>
            </section>
          ))}

          <div className="rw-rules-notice">
            <i className="bi bi-exclamation-triangle" aria-hidden="true" />
            <div>
              <strong>El staff aplica el espíritu de las reglas</strong>
              <p>
                El equipo puede sancionar conductas que vayan contra el espíritu de este
                reglamento aunque no estén listadas literalmente. Si recibiste una sanción y
                crees que fue un error, apela abriendo un ticket en nuestro Discord con tu
                evidencia.
              </p>
              <a
                className="rw-btn rw-btn--discord rw-btn--sm"
                href={DISCORD_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <i className="bi bi-discord" /> Apelar en Discord
              </a>
            </div>
          </div>
        </div>
      </main>

      <footer className="rw-footer">
        <div className="rw-footer-brand">
          <img src={logoNuevo} alt="Rustaco" />
          <span>© Rustaco — Todos los derechos reservados.</span>
        </div>
        <nav className="rw-footer-links">
          <Link to="/">Inicio</Link>
          <Link to="/maps">Maps</Link>
          <Link to="/events">Leaderboard</Link>
          <a href={DISCORD_URL} target="_blank" rel="noopener noreferrer">Discord</a>
        </nav>
      </footer>
    </div>
  );
}
